using System.Collections.Generic;
using UnityEngine;

namespace PaletteRoom
{
    /// <summary>
    /// The built-in palettes, each built on a color-wheel harmony (hues measured on the RYB painter's
    /// wheel) and weighted for 60-30-10: a muted dominant, a supporting secondary, and saturated accents.
    /// The first eight are hand-tuned; the rest are generated by <see cref="ColorHarmony"/> from a chosen
    /// base color, so every one is harmonious by construction.
    /// </summary>
    public static class PalettePresets
    {
        //                                 name                 harmony                          dominant   secondary  accent     neutral    highlight
        static readonly ColorPalette[] Curated =
        {
            // Dusty blue against warm amber, softened by a warm-white dominant.
            new ColorPalette("Scandinavian",      HarmonyRule.Complementary,      "#DCD6CC", "#8A9FBF", "#D98E4A", "#F4F1EB", "#3E5566"),
            // Sapphire, ruby and topaz: the blue–red–yellow primary triad in deep jewel values.
            new ColorPalette("Moody Jewel",       HarmonyRule.Triadic,            "#1F3550", "#6E2338", "#D4A23A", "#2B2B30", "#3D6A99"),
            // Sea blues split against coral and sand, the two hues either side of blue's complement.
            new ColorPalette("Coastal",           HarmonyRule.SplitComplementary, "#E8E1D2", "#7FA7C2", "#2F5D8A", "#F7F6F2", "#E07A5F"),
            // Neighbouring red-oranges through ochre: warm and enveloping.
            new ColorPalette("Terracotta Desert", HarmonyRule.Analogous,          "#D9B99B", "#B5653F", "#D99A2B", "#F1E6D8", "#8A3B24"),
            // Deep teal opposite burnt orange, with mustard and brick riding the warm side.
            new ColorPalette("Mid-Century",       HarmonyRule.Complementary,      "#2B5A66", "#C46A2B", "#E2B13C", "#EFE7DA", "#8B3A2F"),
            // One sage hue in tints and shades.
            new ColorPalette("Monochrome Sage",   HarmonyRule.Monochromatic,      "#9CAF88", "#7D9170", "#4F6146", "#E9EDE4", "#C5D3B8"),
            // Oat, taupe and clay sit side by side on the warm wheel; charcoal grounds them.
            new ColorPalette("Japandi",           HarmonyRule.Analogous,          "#CFC6B8", "#8C7B6B", "#2F2F2F", "#F2EEE7", "#B07D62"),
            // Coral, sun yellow and violet-blue: a playful triad over a peach base.
            new ColorPalette("Sunset Pop",        HarmonyRule.Triadic,            "#F6C1A6", "#F28C8C", "#5B4FC2", "#FFF4EC", "#FFD93C"),
        };

        // Base color + rule; the harmony engine fills in the other four colors.
        static readonly (string name, HarmonyRule rule, string baseColor)[] Generated =
        {
            ("Navy & Brass",       HarmonyRule.Complementary,      "#3B4E6B"),
            ("Olive & Plum",       HarmonyRule.Complementary,      "#7D8656"),
            ("Teal & Terracotta",  HarmonyRule.Complementary,      "#2F6F73"),
            ("Lemon Grove",        HarmonyRule.SplitComplementary, "#D9C46A"),
            ("Berry Patch",        HarmonyRule.SplitComplementary, "#8E3B5E"),
            ("Sea Glass",          HarmonyRule.SplitComplementary, "#7FB8AD"),
            ("Forest Floor",       HarmonyRule.Analogous,          "#5E7A4A"),
            ("Desert Rose",        HarmonyRule.Analogous,          "#C98B86"),
            ("Ocean Depths",       HarmonyRule.Analogous,          "#2E5E7E"),
            ("Primary Studio",     HarmonyRule.Triadic,            "#B8433A"),
            ("Pastel Triad",       HarmonyRule.Triadic,            "#E3B0B8"),
            ("Citrus Burst",       HarmonyRule.Triadic,            "#E08A2E"),
            ("Bohemian",           HarmonyRule.Tetradic,           "#9C4A3C"),
            ("Garden Party",       HarmonyRule.Tetradic,           "#6FA06A"),
            ("Blush Tonal",        HarmonyRule.Monochromatic,      "#D8A7A0"),
            ("Ocean Tonal",        HarmonyRule.Monochromatic,      "#4F7CA8"),
        };

        static IReadOnlyList<ColorPalette> s_All;

        /// <summary>All presets, curated first. Order matches the palette dock.</summary>
        public static IReadOnlyList<ColorPalette> All
        {
            get
            {
                if (s_All != null)
                    return s_All;
                var list = new List<ColorPalette>(Curated);
                foreach (var (name, rule, hex) in Generated)
                {
                    ColorUtility.TryParseHtmlString(hex, out var baseColor);
                    list.Add(ColorHarmony.Generate(baseColor, rule, name));
                }
                s_All = list;
                return s_All;
            }
        }

        public static ColorPalette Default => All[0];
    }
}
